#!/bin/bash
# Prepare API directories and BIND configuration; the official API writes zones and loads them through RNDC.
set -euo pipefail
role=$1
install -d -o bind9-api -g bind -m 2750 /etc/bind/api-zones
install -d -o bind9-api -g bind9-api -m 700 /var/lib/bind9-api /var/lib/bind9-api/backups /run/bind9-api /var/log/bind9-api
touch /etc/bind/bind9-api.conf
chown bind9-api:bind /etc/bind/bind9-api.conf
chmod 640 /etc/bind/bind9-api.conf
# Keep the static domain zone generated by DomainNameService using a separate include.
grep -Fqx 'include "/etc/bind/bind9-api.conf";' /etc/bind/named.conf.local || echo 'include "/etc/bind/bind9-api.conf";' >> /etc/bind/named.conf.local
cat > /etc/bind/named.conf.options <<OPTIONS
options {
    directory "/var/cache/bind";
    recursion no;
    dnssec-validation no;
    empty-zones-enable no;
    allow-query { any; };
    allow-update { none; };
    allow-update-forwarding { none; };
    allow-transfer { __SECONDARY_IP__; };
    notify explicit;
    also-notify { __SECONDARY_IP__; };
};
OPTIONS
if [ "$role" = secondary ]; then
    sed -i 's/allow-transfer { __SECONDARY_IP__; };/allow-transfer { none; };/; s/notify explicit;/notify no;/; /also-notify/d' /etc/bind/named.conf.options
fi
# Disable network updates for static zones as well to prevent bypassing API authentication.
sed -i 's/allow-update { any; };/allow-update { none; };/g; s/allow-transfer { any; };/allow-transfer { __SECONDARY_IP__; };/g' /etc/bind/named.conf.zones
if [ ! -s /etc/bind/rndc.key ]; then rndc-confgen -a; fi
chown root:bind /etc/bind/rndc.key
chmod 640 /etc/bind/rndc.key
php8.5 /opt/dns-hosting/init-bind-api-nameserver.php
named-checkconf
# DomainNameService starts BIND later; the API waits for its local control interface.
(
    for attempt in $(seq 1 120); do
        if runuser -u bind9-api -- rndc status >/dev/null 2>&1; then
            exec runuser -u bind9-api -- php8.5 /opt/bind9-api/start_bind9_api.php
        fi
        sleep 1
    done
    echo 'BIND API 启动失败：等待 RNDC 超时' >&2
    exit 1
) >> /var/log/bind9-api/start.log 2>&1 &
